type agreementMixedUnusedOwner struct{ Field, Definition, Root, Node int }

// Discarded definitions own their whole consumed native source, before code priority.
func agreementMixedUnusedOwners(native agreementNativeOwnerSource, check *agreementNativeCheckSource, tree *agreementNativeProseAddressTree) ([]agreementMixedUnusedOwner, bool) {
	var owners []agreementMixedUnusedOwner
	if !tree.Valid {
		return nil, false
	}
	used := make(map[graph.Span]bool)
	for fi, field := range check.Fields {
		if field.Code || field.Comment || field.Escaped || field.DefinitionOwner < 0 || !slices.Contains(field.Targets, "A") {
			continue
		}
		if len(field.Targets) != 1 || field.DefinitionOwner >= len(native.Definitions) || used[field.Span] {
			return nil, false
		}
		definition := &native.Definitions[field.DefinitionOwner]
		if definition.Span.Start < 0 || definition.Span.Stop <= definition.Span.Start || field.Span.Start < definition.Span.Start || field.Span.Stop > definition.Span.Stop || field.Span.Stop <= field.Span.Start || definition.Name.Start < definition.Span.Start || definition.Name.Stop > definition.Span.Stop {
			return nil, false
		}
		candidate := -1
		for di := range tree.Definitions {
			d := &tree.Definitions[di]
			if !d.Found || d.Root != field.DefinitionOwner+1 || d.Root >= len(tree.Trees) || d.Root < 1 || d.Node != 0 || len(tree.Trees[d.Root]) == 0 || tree.Trees[d.Root][0].Kind != extast.KindFootnote.String() || d.Label != definition.Label || d.Bounds.Parent != definition.Parent || d.Bounds.Span != definition.Span || d.Bounds.Label != definition.Name {
				continue
			}
			if candidate >= 0 {
				return nil, false
			}
			candidate = di
		}
		if candidate < 0 {
			return nil, false
		}
		used[field.Span] = true
		d := &tree.Definitions[candidate]
		owners = append(owners, agreementMixedUnusedOwner{Field: fi, Definition: field.DefinitionOwner, Root: d.Root, Node: d.Node})
	}
	return owners, len(owners) > 0
}

type agreementMixedRename struct {
	Field    int
	Span     graph.Span
	Old, New string
}

// Each private comparison changes one selected owner class, or their complete union.
func agreementMixedPrivate(body string, native agreementNativeOwnerSource, check *agreementNativeCheckSource, sites []agreementNativeCodePayloadSite, tree *agreementNativeProseAddressTree, mode string) (string, []agreementMixedRename, bool) {
	if strings.Contains(body, "q") || (mode != "info" && mode != "unused" && mode != "both") {
		return "", nil, false
	}
	info, iok := agreementNativeInfoOwners(native, check, sites)
	unused, uok := agreementMixedUnusedOwners(native, check, tree)
	if !iok || !uok {
		return "", nil, false
	}
	var fields []int
	if mode != "unused" {
		for _, owner := range info {
			fields = append(fields, owner.Field)
		}
	}
	if mode != "info" {
		for _, owner := range unused {
			fields = append(fields, owner.Field)
		}
	}
	slices.Sort(fields)
	used := make(map[graph.Span]bool)
	private := []byte(body)
	var changes []agreementMixedRename
	for _, fi := range fields {
		field := check.Fields[fi]
		if field.Span.Start < 0 || field.Span.Stop > len(body) || field.Span.Stop <= field.Span.Start || used[field.Span] || len(field.Word) < 4 || !strings.HasPrefix(field.Word, "[[") || !strings.HasSuffix(field.Word, "]]") || body[field.Span.Start:field.Span.Stop] != field.Word {
			return "", nil, false
		}
		if field.DefinitionOwner >= 0 {
			if native.Definitions[field.DefinitionOwner].Span.Stop > len(body) {
				return "", nil, false
			}
		} else if native.Code[field.CodeOwner].Span.Stop > len(body) {
			return "", nil, false
		}
		inner := field.Word[2 : len(field.Word)-2]
		link, ok := graph.ParseWikilink(inner)
		if !ok || link.Target != "A" || strings.ContainsAny(inner, "[]\r\n") || strings.ContainsRune(inner, 96) {
			return "", nil, false
		}
		start := field.Span.Start + 2 + strings.Index(inner, link.Target)
		stop := start + len(link.Target)
		if start < field.Span.Start+2 || stop > field.Span.Stop-2 || body[start:stop] != link.Target {
			return "", nil, false
		}
		used[field.Span] = true
		private[start] = 'q'
		changes = append(changes, agreementMixedRename{Field: fi, Span: graph.Span{Start: start, Stop: stop}, Old: "A", New: "q"})
	}
	return string(private), changes, len(changes) > 0
}

func agreementMixedCurrent(failures []agreementFailure) map[string]int {
	current := make(map[string]int)
	for i := range failures {
		current[agreementSignature(&failures[i])]++
	}
	return current
}

type agreementMixedVariant struct {
	Name, Body string
	Check      agreementNativeCheckSource
	Targets    []string
	Signatures map[string]int
	Changes    []agreementMixedRename
}
