func TestAgreementMixedInfoUnusedSource(t *testing.T) {
	t.Parallel()
	witnesses := agreementMixedWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			info, ok := agreementNativeInfoOwners(w.Native, &w.Check, w.Sites)
			if !ok || !cmp.Equal(info, w.Info) {
				t.Fatal("caught: complete selected native info owners")
			}
			unused, ok := agreementMixedUnusedOwners(w.Native, &w.Check, &w.Tree)
			if !ok || !cmp.Equal(unused, w.Unused) {
				t.Fatal("caught: complete selected discarded definition owners")
			}
			for vi := range w.Variants {
				v := &w.Variants[vi]
				t.Run(v.Name, func(t *testing.T) {
					native := agreementNativeOwnerReading(v.Body)
					if diff := cmp.Diff(w.Native, native); diff != "" {
						t.Fatalf("caught: complete mixed native facts (-want +got):\n%s", diff)
					}
					if diff := cmp.Diff(v.Check, agreementNativeCheckReading(v.Body, native)); diff != "" {
						t.Fatalf("caught: complete mixed physical fields (-want +got):\n%s", diff)
					}
					if diff := cmp.Diff(w.Sites, agreementNativeCodePayloadSites(v.Body)); diff != "" {
						t.Fatalf("caught: complete mixed native code declarations (-want +got):\n%s", diff)
					}
					if diff := cmp.Diff(w.HTML, agreementNativeHTMLAddressSites(v.Body)); diff != "" {
						t.Fatalf("caught: complete mixed native HTML declarations (-want +got):\n%s", diff)
					}
					if diff := cmp.Diff(w.Tree, agreementNativeProseAddressTreeReading(v.Body, nil)); diff != "" {
						t.Fatalf("caught: complete mixed declaration trees (-want +got):\n%s", diff)
					}
					if diff := cmp.Diff(v.Targets, judge.LinkTargets(v.Body)); diff != "" {
						t.Fatalf("caught: complete mixed check targets (-want +got):\n%s", diff)
					}
					if v.Name == "original" {
						if v.Body != w.Body || len(v.Changes) != 0 {
							t.Fatal("caught: complete mixed original body")
						}
						return
					}
					private, changes, ok := agreementMixedPrivate(w.Body, w.Native, &w.Check, w.Sites, &w.Tree, v.Name)
					if !ok || private != v.Body || !cmp.Equal(changes, v.Changes) {
						t.Fatal("caught: exact independent mixed ownership projection")
					}
				})
			}
		})
	}
}

func TestAgreementMixedInfoUnusedPublic(t *testing.T) {
	t.Parallel()
	witnesses := agreementMixedWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			for vi := range w.Variants {
				v := &w.Variants[vi]
				t.Run(v.Name, func(t *testing.T) {
					c := agreementCase{Body: v.Body}
					raw, page := agreementIsolatedPage(t, c)
					if diff := cmp.Diff(w.Page, page); diff != "" {
						t.Fatalf("caught: complete unchanged mixed public ledger (-want +got):\n%s", diff)
					}
					parts, ok := agreementCodeWindowParts(raw.HTML)
					if diff := cmp.Diff(w.Parts, parts); !ok || diff != "" {
						t.Fatalf("caught: complete unchanged mixed code payloads (-want +got):\n%s", diff)
					}
					failures := agreementPageFailures(v.Body, &raw, &page)
					failures = append(failures, agreementFragmentFailures(t, []agreementCase{c}, []agreementHTML{page})[0]...)
					if !maps.Equal(v.Signatures, agreementMixedCurrent(failures)) {
						t.Fatal("caught: complete mixed P0-P4 signed pools")
					}
				})
			}
		})
	}
}

func agreementMixedInfoUnusedDifference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || f.Property != "P1" || f.Identity != "citation-occurrences" || f.Direction != "judge-only" || f.Multiplicity < 1 || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound {
		return "", "", ""
	}
	witnesses := agreementMixedWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		if c.Body != w.Body {
			continue
		}
		if w.Selected[agreementSignature(f)] != 1 {
			return "", "", ""
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		sites := agreementNativeCodePayloadSites(c.Body)
		tree := agreementNativeProseAddressTreeReading(c.Body, nil)
		parts, pok := agreementCodeWindowParts(raw)
		info, iok := agreementNativeInfoOwners(native, &check, sites)
		unused, uok := agreementMixedUnusedOwners(native, &check, &tree)
		private, changes, ok := agreementMixedPrivate(c.Body, native, &check, sites, &tree, "both")
		if !ok || !iok || !uok || !pok || private != w.Variants[3].Body || !cmp.Equal(changes, w.Variants[3].Changes) || !cmp.Equal(info, w.Info) || !cmp.Equal(unused, w.Unused) || !cmp.Equal(native, w.Native) || !cmp.Equal(check, w.Check) || !cmp.Equal(sites, w.Sites) || !cmp.Equal(tree, w.Tree) || !cmp.Equal(agreementNativeHTMLAddressSites(c.Body), w.HTML) || !cmp.Equal(judge.LinkTargets(c.Body), w.Targets) || !cmp.Equal(parts, w.Parts) || !cmp.Equal(*page, w.Page) || !maps.Equal(agreementMixedCurrent(failures), w.Signatures) {
			return "", "", ""
		}
		return "debt", "#1011 stages 4 and 5", "judge"
	}
	return "", "", ""
}

func TestAgreementMixedInfoUnusedDifferences(t *testing.T) {
	t.Parallel()
	witnesses := agreementMixedWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			c := agreementCase{Body: w.Body}
			raw, page := agreementIsolatedPage(t, c)
			failures := agreementPageFailures(w.Body, &raw, &page)
			failures = append(failures, agreementFragmentFailures(t, []agreementCase{c}, []agreementHTML{page})[0]...)
			seen := 0
			for _, f := range failures {
				if w.Selected[agreementSignature(&f)] != 1 {
					continue
				}
				seen++
				k, a, v := agreementMixedInfoUnusedDifference(c, &f, raw.HTML, &page, failures)
				if k != "debt" || a != "#1011 stages 4 and 5" || v != "judge" {
					t.Fatal("caught: mixed info/unused lost its declared authority")
				}
				for _, alter := range []struct {
					Name   string
					Change func(*agreementFailure)
				}{
					{"property", func(f *agreementFailure) { f.Property = "P2" }}, {"identity", func(f *agreementFailure) { f.Identity = "other" }}, {"direction", func(f *agreementFailure) { f.Direction = "other" }}, {"target", func(f *agreementFailure) { f.Tuple.Target = "outside" }}, {"role", func(f *agreementFailure) { f.Tuple.SourceRole = "other" }}, {"state", func(f *agreementFailure) { f.Tuple.State = "other" }}, {"section", func(f *agreementFailure) { f.Tuple.Section = "other" }}, {"multiplicity", func(f *agreementFailure) { f.Multiplicity++ }}, {"cut", func(f *agreementFailure) { f.Cut = "other" }}, {"fragment", func(f *agreementFailure) { f.Fragment = "other" }}, {"page", func(f *agreementFailure) { f.PagePresent = true }}, {"judge", func(f *agreementFailure) { f.JudgeAccepted = true }}, {"excerpt", func(f *agreementFailure) { f.ExcerptFound = true }},
				} {
					t.Run(alter.Name, func(t *testing.T) {
						changed := f
						alter.Change(&changed)
						kind, authority, wrong := agreementMixedInfoUnusedDifference(c, &changed, raw.HTML, &page, failures)
						if kind != "" || authority != "" || wrong != "" {
							t.Fatal("caught: mixed info/unused borrowed another signed face")
						}
					})
				}
				for _, other := range []agreementCase{{Body: w.Body + "\n"}, {Body: w.Body, Title: "A"}, {Body: w.Body, Companions: capturedBodies{"Notes/Other.md": "outside"}}} {
					kind, authority, wrong := agreementMixedInfoUnusedDifference(other, &f, raw.HTML, &page, failures)
					if kind != "" || authority != "" || wrong != "" {
						t.Fatal("caught: mixed info/unused borrowed another complete body or context")
					}
				}
				for i := range failures {
					missing := slices.Delete(slices.Clone(failures), i, i+1)
					k, a, v = agreementMixedInfoUnusedDifference(c, &f, raw.HTML, &page, missing)
					if k != "" || a != "" || v != "" {
						t.Fatal("caught: mixed info/unused borrowed an incomplete whole signed pool")
					}
				}
				extra := append(slices.Clone(failures), f)
				k, a, v = agreementMixedInfoUnusedDifference(c, &f, raw.HTML, &page, extra)
				if k != "" || a != "" || v != "" {
					t.Fatal("caught: mixed info/unused borrowed another whole signed pool")
				}
				changed := page
				changed.Headings = append(slices.Clone(page.Headings), "outside")
				k, a, v = agreementMixedInfoUnusedDifference(c, &f, raw.HTML, &changed, failures)
				if k != "" || a != "" || v != "" {
					t.Fatal("caught: mixed info/unused borrowed another whole public ledger")
				}
				k, a, v = agreementMixedInfoUnusedDifference(c, &f, raw.HTML+"<code>outside</code>", &page, failures)
				if k != "" || a != "" || v != "" {
					t.Fatal("caught: mixed info/unused borrowed changed field-free code text")
				}
			}
			if seen != len(w.Selected) {
				t.Fatal("mixed info/unused selected receipt setup")
			}
		})
	}
}

func TestAgreementMixedInfoUnusedCausalPools(t *testing.T) {
	t.Parallel()
	witnesses := agreementMixedWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			c := agreementCase{Body: w.Body}
			raw, page := agreementIsolatedPage(t, c)
			failures := agreementPageFailures(w.Body, &raw, &page)
			failures = append(failures, agreementFragmentFailures(t, []agreementCase{c}, []agreementHTML{page})[0]...)
			var p0, p1 agreementFailure
			n0, n1 := 0, 0
			for _, f := range failures {
				if f.Tuple.Target != "A" {
					continue
				}
				if f.Property == "P0" && f.Identity == "diagnostic-html" && f.Direction == "diagnostic-only" {
					p0 = f
					n0++
				}
				if f.Property == "P1" && f.Identity == "citation-occurrences" && f.Direction == "judge-only" {
					p1 = f
					n1++
				}
			}
			if n0 != 1 || n1 != 1 || p0.Multiplicity != len(w.Unused) || p1.Multiplicity != len(w.Info)+len(w.Unused) {
				t.Fatal("caught: mixed signed counts equal their complete declared source owners")
			}
			for vi := range w.Variants {
				v := &w.Variants[vi]
				if v.Name == "original" {
					if !maps.Equal(v.Signatures, w.Signatures) {
						t.Fatal("caught: complete mixed original signed pool")
					}
					continue
				}
				expected := maps.Clone(w.Signatures)
				count := len(w.Info)
				switch v.Name {
				case "unused":
					count = len(w.Unused)
				case "both":
					count += len(w.Unused)
				}
				delete(expected, agreementSignature(&p1))
				remainder := p1
				remainder.Multiplicity -= count
				if remainder.Multiplicity > 0 {
					expected[agreementSignature(&remainder)]++
				}
				private := p1
				private.Tuple.Target = "q"
				private.Multiplicity = count
				expected[agreementSignature(&private)]++
				if v.Name != "info" {
					delete(expected, agreementSignature(&p0))
					diagnostic := p0
					diagnostic.Tuple.Target = "q"
					expected[agreementSignature(&diagnostic)]++
				}
				if !maps.Equal(expected, v.Signatures) {
					t.Fatal("caught: info changes only P1; discarded definitions change P0/P1; every unselected P0-P4 member stays identical")
				}
			}
		})
	}
}

func TestAgreementMixedInfoUnusedOwnershipRefusals(t *testing.T) {
	for _, w := range agreementMixedWitnesses() {
		owner := w.Unused[0]
		for _, tc := range []struct {
			Name   string
			Change func(*agreementNativeOwnerSource, *agreementNativeCheckSource, *agreementNativeProseAddressTree)
		}{
			{"missing definitions", func(n *agreementNativeOwnerSource, _ *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				n.Definitions = nil
			}},
			{"invalid tree", func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, r *agreementNativeProseAddressTree) {
				r.Valid = false
			}},
			{"missing roots", func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, r *agreementNativeProseAddressTree) {
				r.Trees = nil
			}},
			{"missing declarations", func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, r *agreementNativeProseAddressTree) {
				r.Definitions = nil
			}},
			{"ambiguous declaration", func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, r *agreementNativeProseAddressTree) {
				for _, d := range r.Definitions {
					if d.Root == owner.Root {
						r.Definitions = append(r.Definitions, d)
						return
					}
				}
			}},
			{"other root kind", func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, r *agreementNativeProseAddressTree) {
				r.Trees[owner.Root][0].Kind = ast.KindDocument.String()
			}},
			{"duplicate physical field", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				c.Fields = append(c.Fields, c.Fields[owner.Field])
			}},
			{"outside definition", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				c.Fields[owner.Field].DefinitionOwner = len(w.Native.Definitions)
			}},
			{"clipped consumed start", func(n *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				n.Definitions[owner.Definition].Span.Start = c.Fields[owner.Field].Span.Stop
			}},
			{"clipped consumed stop", func(n *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				n.Definitions[owner.Definition].Span.Stop = c.Fields[owner.Field].Span.Start
			}},
			{"outside field start", func(n *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				c.Fields[owner.Field].Span.Start = n.Definitions[owner.Definition].Span.Start - 1
			}},
			{"outside field stop", func(n *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				c.Fields[owner.Field].Span.Stop = n.Definitions[owner.Definition].Span.Stop + 1
			}},
			{"empty field", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				c.Fields[owner.Field].Span.Stop = c.Fields[owner.Field].Span.Start
			}},
			{"outside name", func(n *agreementNativeOwnerSource, _ *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				n.Definitions[owner.Definition].Name.Start = n.Definitions[owner.Definition].Span.Start - 1
			}},
			{"empty selected set", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				c.Fields = nil
			}},
			{"already check code", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				for _, o := range w.Unused {
					c.Fields[o.Field].Code = true
				}
			}},
			{"comment", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				for _, o := range w.Unused {
					c.Fields[o.Field].Comment = true
				}
			}},
			{"escaped", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				for _, o := range w.Unused {
					c.Fields[o.Field].Escaped = true
				}
			}},
			{"different target", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				for _, o := range w.Unused {
					c.Fields[o.Field].Targets = []string{"other"}
				}
			}},
			{"multiple targets", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				c.Fields[owner.Field].Targets = []string{"A", "other"}
			}},
			{"missing definition role", func(_ *agreementNativeOwnerSource, c *agreementNativeCheckSource, _ *agreementNativeProseAddressTree) {
				for _, o := range w.Unused {
					c.Fields[o.Field].DefinitionOwner = -1
				}
			}},
			{"missing root node", func(_ *agreementNativeOwnerSource, _ *agreementNativeCheckSource, r *agreementNativeProseAddressTree) {
				r.Trees[owner.Root] = nil
			}},
		} {
			t.Run(w.Name+"/"+tc.Name, func(t *testing.T) {
				n := w.Native
				n.Definitions = slices.Clone(n.Definitions)
				c := w.Check
				c.Fields = slices.Clone(c.Fields)
				r := w.Tree
				r.Definitions = slices.Clone(r.Definitions)
				r.Trees = slices.Clone(r.Trees)
				for i := range r.Trees {
					r.Trees[i] = slices.Clone(r.Trees[i])
				}
				tc.Change(&n, &c, &r)
				if _, ok := agreementMixedUnusedOwners(n, &c, &r); ok {
					t.Fatal("caught: mixed unused source borrowed absent, clipped or ambiguous ownership")
				}
			})
		}
		for _, tc := range []struct {
			Name   string
			Change func(*agreementNativeProseAddressDefinition)
		}{
			{"not found", func(d *agreementNativeProseAddressDefinition) { d.Found = false }},
			{"document root", func(d *agreementNativeProseAddressDefinition) { d.Root = 0 }},
			{"other root", func(d *agreementNativeProseAddressDefinition) { d.Root++ }},
			{"other node", func(d *agreementNativeProseAddressDefinition) { d.Node++ }},
			{"other label", func(d *agreementNativeProseAddressDefinition) { d.Label = "other" }},
			{"other parent", func(d *agreementNativeProseAddressDefinition) { d.Bounds.Parent = "other" }},
			{"other consumed start", func(d *agreementNativeProseAddressDefinition) { d.Bounds.Span.Start++ }},
			{"other consumed stop", func(d *agreementNativeProseAddressDefinition) { d.Bounds.Span.Stop-- }},
			{"other name start", func(d *agreementNativeProseAddressDefinition) { d.Bounds.Label.Start++ }},
			{"other name stop", func(d *agreementNativeProseAddressDefinition) { d.Bounds.Label.Stop-- }},
		} {
			t.Run(w.Name+"/"+tc.Name, func(t *testing.T) {
				r := w.Tree
				r.Definitions = slices.Clone(r.Definitions)
				for i := range r.Definitions {
					if r.Definitions[i].Root == owner.Root {
						tc.Change(&r.Definitions[i])
					}
				}
				if _, ok := agreementMixedUnusedOwners(w.Native, &w.Check, &r); ok {
					t.Fatal("caught: mixed unused source borrowed another native declaration map")
				}
			})
		}
	}
}

func TestAgreementMixedInfoUnusedPrivateRefusals(t *testing.T) {
	for _, w := range agreementMixedWitnesses() {
		for _, mode := range []string{"", "original", "other"} {
			if _, _, ok := agreementMixedPrivate(w.Body, w.Native, &w.Check, w.Sites, &w.Tree, mode); ok {
				t.Fatal("caught: mixed projection borrowed another owner selection")
			}
		}
		if _, _, ok := agreementMixedPrivate(w.Body+"q", w.Native, &w.Check, w.Sites, &w.Tree, "both"); ok {
			t.Fatal("caught: mixed projection private namespace collides")
		}
		for _, fi := range []int{w.Info[0].Field, w.Unused[0].Field} {
			field := w.Check.Fields[fi]
			t.Run(w.Name+"/changed word bytes/"+field.Word, func(t *testing.T) {
				body := []byte(w.Body)
				body[field.Span.Start+2] = 'X'
				if _, _, ok := agreementMixedPrivate(string(body), w.Native, &w.Check, w.Sites, &w.Tree, "both"); ok {
					t.Fatal("caught: mixed projection borrowed changed physical word bytes")
				}
			})
			t.Run(w.Name+"/clipped body/"+field.Word, func(t *testing.T) {
				if _, _, ok := agreementMixedPrivate(w.Body[:field.Span.Start], w.Native, &w.Check, w.Sites, &w.Tree, "both"); ok {
					t.Fatal("caught: mixed projection borrowed fields beyond the body")
				}
			})
			t.Run(w.Name+"/non-wikilink wrapper/"+field.Word, func(t *testing.T) {
				check := w.Check
				check.Fields = slices.Clone(check.Fields)
				word := []byte(field.Word)
				word[0], word[1] = '~', '~'
				check.Fields[fi].Word = string(word)
				body := []byte(w.Body)
				copy(body[field.Span.Start:field.Span.Stop], word)
				if _, _, ok := agreementMixedPrivate(string(body), w.Native, &check, w.Sites, &w.Tree, "both"); ok {
					t.Fatal("caught: mixed projection borrowed a different physical field kind")
				}
			})
		}
		t.Run(w.Name+"/consumed definition beyond body", func(t *testing.T) {
			native := w.Native
			native.Definitions = slices.Clone(native.Definitions)
			tree := w.Tree
			tree.Definitions = slices.Clone(tree.Definitions)
			owner := w.Unused[0]
			native.Definitions[owner.Definition].Span.Stop = len(w.Body) + 1
			for i := range tree.Definitions {
				if tree.Definitions[i].Root == owner.Root {
					tree.Definitions[i].Bounds.Span.Stop = len(w.Body) + 1
				}
			}
			if _, _, ok := agreementMixedPrivate(w.Body, native, &w.Check, w.Sites, &tree, "unused"); ok {
				t.Fatal("caught: mixed projection borrowed a consumed definition outside the body")
			}
		})
	}
}

func TestAgreementMixedInfoUnusedSuffixRefusal(t *testing.T) {
	for _, w := range agreementMixedWitnesses() {
		fi := w.Info[0].Field
		field := w.Check.Fields[fi]
		check := w.Check
		check.Fields = slices.Clone(check.Fields)
		word := []byte(field.Word)
		word[len(word)-2], word[len(word)-1] = '~', '~'
		check.Fields[fi].Word = string(word)
		body := []byte(w.Body)
		copy(body[field.Span.Start:field.Span.Stop], word)
		if _, _, ok := agreementMixedPrivate(string(body), w.Native, &check, w.Sites, &w.Tree, "info"); ok {
			t.Fatal("caught: mixed projection borrowed a different field closing token")
		}
	}
}

func TestAgreementMixedInfoUnusedWholeOwnerSet(t *testing.T) {
	for _, w := range agreementMixedWitnesses() {
		names := make([]string, 0, len(w.Variants))
		for _, v := range w.Variants {
			names = append(names, v.Name)
		}
		if !slices.Equal(names, []string{"original", "info", "unused", "both"}) {
			t.Fatal("caught: mixed comparisons retain every declared selection in order")
		}
		fields := make(map[int]bool)
		for _, o := range w.Info {
			if fields[o.Field] {
				t.Fatal("caught: mixed owner classes overlap")
			}
			fields[o.Field] = true
		}
		for _, o := range w.Unused {
			if fields[o.Field] {
				t.Fatal("caught: mixed owner classes overlap")
			}
			fields[o.Field] = true
		}
		for _, v := range w.Variants {
			if v.Name == "original" {
				continue
			}
			expected := make(map[int]bool)
			if v.Name != "unused" {
				for _, o := range w.Info {
					expected[o.Field] = true
				}
			}
			if v.Name != "info" {
				for _, o := range w.Unused {
					expected[o.Field] = true
				}
			}
			actual := make(map[int]bool)
			for _, ch := range v.Changes {
				if actual[ch.Field] || ch.Old != "A" || ch.New != "q" || ch.Span.Stop-ch.Span.Start != 1 {
					t.Fatal("caught: mixed selection owns each equal-width physical target once")
				}
				actual[ch.Field] = true
			}
			if !maps.Equal(expected, actual) {
				t.Fatal("caught: mixed selection owns its whole declared field set")
			}
			expectedCheck := w.Check
			expectedCheck.Fields = slices.Clone(expectedCheck.Fields)
			for _, ch := range v.Changes {
				f := &expectedCheck.Fields[ch.Field]
				start := ch.Span.Start - f.Span.Start
				stop := ch.Span.Stop - f.Span.Start
				word := []byte(f.Word)
				copy(word[start:stop], ch.New)
				f.Word = string(word)
				f.Targets = []string{"q"}
			}
			expectedCheck.Targets = nil
			for _, f := range expectedCheck.Fields {
				if !f.Code && !f.Comment && !f.Escaped {
					expectedCheck.Targets = append(expectedCheck.Targets, f.Targets...)
				}
			}
			if !cmp.Equal(expectedCheck, v.Check) {
				t.Fatal("caught: every unselected mixed physical field and role stays identical")
			}
		}
	}
}
